// lib/schemas.js
import { z } from 'zod';

export const postSchema = z.object({
  title: z.string()
    .min(1, 'Title is required')
    .max(100, 'Title must be under 100 characters')
    .trim(),
  content: z.string()
    .min(10, 'Content must be at least 10 characters')
    .max(5000, 'Content too long'),
  published: z.boolean().optional(),
});

