# Better User Experience

Instead of a single error message, you can return an object with errors for each field.

```js
if (!result.success) {
  const fieldErrors = result.error.flatten().fieldErrors;
  return { errors: fieldErrors };
}
```

Then in the form, you can show errors next to each input:

```jsx
{state?.errors?.title && <span>{state.errors.title[0]}</span>}
```

slides.codeSnippet:
// app/actions.js
'use server';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { postSchema } from '@/lib/schemas';

export async function createPost(prevState, formData) {
  const result = postSchema.safeParse({
    title: formData.get('title'),
    content: formData.get('content'),
  });

  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }

  await prisma.post.create({ data: result.data });
  revalidatePath('/posts');
  return { success: true };
}

// components/NewPostForm.js
'use client';
import { useFormState } from 'react-dom';
import { createPost } from '@/app/actions';

const initialState = {};

export default function NewPostForm() {
  const [state, formAction] = useFormState(createPost, initialState);

  return (
    <form action={formAction}>
      <div>
        <input name="title" placeholder="Title" />
        {state?.errors?.title && <span className="error">{state.errors.title[0]}</span>}
      </div>
      <div>
        <textarea name="content" placeholder="Content" />
        {state?.errors?.content && <span className="error">{state.errors.content[0]}</span>}
      </div>
      <button type="submit">Create</button>
      {state?.success && <p className="success">Post created!</p>}
    </form>
  );
}

slides.content:
You can add custom validation logic. For example, ensure the title isn't a duplicate:

```js
z.string().superRefine(async (val, ctx) => {
  const existing = await prisma.post.findUnique({ where: { title: val } });
  if (existing) ctx.addIssue({ code: 'custom', message: 'Title already exists' });
});
```

Zod can even run async checks!
